package hmgapi.hook;public class ModContext {public boolean active=true,external=true;public final java.util.Map<String,MethodHook> hooks=new java.util.HashMap<String,MethodHook>();public final java.util.List<String> logs=new java.util.ArrayList<String>();public boolean enabled(){return active;}public boolean settingBoolean(String s,boolean b){if(!s.equals("external_dongle"))throw new AssertionError(s);return external;}public void hook(ClassLoader c,String id,MethodHook h){if(hooks.put(id,h)!=null)throw new AssertionError("duplicate");}public void log(String s){logs.add(s);}}
